import{_ as t,c as s,o as i,j as e,a as r}from"./chunks/framework.Dnh4IO1K.js";const f=JSON.parse('{"title":"卷二·23","description":"易小帖 - 卷二·23","frontmatter":{"title":"卷二·23","description":"易小帖 - 卷二·23"},"headers":[],"relativePath":"classics/yixiaotie/063.md","filePath":"classics/yixiaotie/063.md"}'),o={name:"classics/yixiaotie/063.md"};function c(n,a,l,d,p,m){return i(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"卷二·23",tabindex:"-1"},[r("卷二·23 "),e("a",{class:"header-anchor",href:"#卷二·23","aria-label":"Permalink to “卷二·23”"},"​")],-1),e("p",null,"《周禮》：「太卜掌三易之法，一曰連山，二曰歸藏，三曰周易。」鄭康成謂：「連山夏易，歸藏商易，與周易而三。」此必師承有據之說。故《禮運》引孔子曰：「我欲觀殷道，是故之宋，而不足徴也，吾得坤乾焉。」註者謂：即歸藏之書，其名坤乾者，以《周易》首乾，商易首坤也。然又名歸藏，以《大傳》曰坤以藏之也。由此而推，則連山為夏易可知。故乾寶謂：連山者列山氏之書也。而夏人因之。歸藏軒轅氏之書也，而商人因之。小成者，伏羲之易也，而文王因之。則以連山歸藏適與炎黃二帝氏號相合，則必二帝原有其書，而夏商因而用之，此與皇甫謐《帝王世紀》夏人因炎帝而曰連山，商人因黃帝而曰歸藏正同。若杜子春、賈公彥輩註三易謂：連山作於伏羲，歸藏作於黃帝，合周易為三易。則以連山屬伏羲為夏易所因之書，與連山本神農，周易本伏羲之說大相刺謬。而後儒祖其說，以闢康成。且有謂連山歸藏並非夏商之易，則並賈杜亦矛盾矣。賈杜謂夏易本羲易，未嘗謂有羲易無夏易也。正惟夏商原有易，而周官太卜掌卜筮之法，則三易兼用，故並及之。觀《左傳》、《國語》筮卦，有遇艮之八、泰之八語，註者謂：夏商易佔變，不用九六，而用七八，故雲。《公羊傳疏》：孔子欲作春秋，卜之，得陽豫之卦，宋氏雲，此夏商之卦名。則明明夏商有易，且亦明列之。三易之數，為太卜兼用，與周官同，而不學之徒尚謂，夏時非易名，羲易非夏易，何其陋乎。",-1)])])}const x=t(o,[["render",c]]);export{f as __pageData,x as default};
